	\framesubtitle{${2:页面副标题}}
	${0:正文内容}
\end{frame}

latex-workshop.intellisense.atSuggestion.@campus-fragile:
\begin{frame}[fragile]{${1:页面标题}}
	${0:代码或 verbatim 内容}
\end{frame}

latex-workshop.intellisense.atSuggestion.@campus-chapter:
\begin{chapter}[${1:assets/背景图片}]{${2:maincolor}}{${3:章节标题}}
	${0:章节说明}
\end{chapter}

latex-workshop.intellisense.atSuggestion.@campus-paper:
\begin{paperframe}[${1:阶段，如 Method}]{${2:论文标题}}{${3:引用键；多篇用逗号分隔}}
	${0:论文讲解内容}
\end{paperframe}

latex-workshop.intellisense.atSuggestion.@campus-paper-figure:
