	\fitfigure[width=${4:.9},height=${5:.58},page=${6:1}]{${7:assets/论文图.pdf}}{${8:图注}}
\end{paperframe}

latex-workshop.intellisense.atSuggestion.@campus-right-image:
\begin{rightimageframe}[image width=${1:.40}]{${2:页面标题}}{${3:assets/右侧图片}}
	\framesubtitle{${4:页面副标题}}
	${0:左侧正文内容}
\end{rightimageframe}

latex-workshop.intellisense.atSuggestion.@campus-two-figures:
