		\fitfigure[width=${1:.40},height=${2:.50}]{${3:assets/左图}}{${4:左图图注}}
	\end{column}
	\begin{column}{.48\textwidth}
		\fitfigure[width=${5:.40},height=${6:.50}]{${7:assets/右图}}{${8:右图图注}}
	\end{column}
\end{columns}

